/** Bancos de foto por nicho. financeiro cobre a maioria das isenções + o BCB. */
export const HERO_BUCKETS: Record<string, string[]> = {
  financeiro: FINANCEIRO,
  viagens: VIAGENS,
  saude: SAUDE,
  veiculos: VEICULOS,
  joias: JOIAS,
  educacao: EDUCACAO,
};

/**
 * Mapeia o nicho (CNAE) + o nome da isenção pro banco de fotos. Casa por
 * palavra-chave; o que não bater cai em "financeiro" (a maioria das isenções).
 */
export function bucketParaNicho(nicho?: string | null, isencaoNome?: string | null): string {
  const t = `${nicho ?? ""} ${isencaoNome ?? ""}`.toLowerCase();
  if (/viag|turis|milha|cadastur|a[eé]re|aeroport/.test(t)) return "viagens";
  if (/sa[uú]de|m[eé]dic|cl[ií]nic|odonto|hospital|\bans\b|farm[aá]c/.test(t)) return "saude";
  if (/ve[ií]cul|autom[oó]|autom[oó]vel|\bcarro|prote[cç][aã]o veicular|seguro auto/.test(t)) return "veiculos";
  if (/joia|joalh|ourives|metais preciosos|pedras preciosas|\bgema/.test(t)) return "joias";
  if (/bolsa|educa[cç]|ensino|\bescola|universi|faculdad|estud/.test(t)) return "educacao";
  return "financeiro";
}

/**
 * Sorteia a foto de fundo do hero do banco pedido e devolve o valor CSS pronto
 * pro slot {{HERO_BG_CSS}}: "url('data:...')" ou "none" (sem foto → só o
 * gradiente da marca). Banco vazio/inexistente cai no financeiro. `rnd` injetável.
 */
export function pickHeroBgCss(bucket: string = "financeiro", rnd: () => number = Math.random): string {
  const arr = HERO_BUCKETS[bucket]?.length ? HERO_BUCKETS[bucket] : HERO_BUCKETS.financeiro;
  if (!arr || arr.length === 0) return "none";
  const uri = arr[Math.floor(rnd() * arr.length)] ?? arr[0];
  return `url('${uri}')`;
}
